    wirkung_staerke: ['niedrig','mittel','hoch','unklar'].includes(b.wirkung_staerke) ? b.wirkung_staerke : 'unklar',
    begruendung_tickerbezug: b.begruendung_tickerbezug || '',
    titel: orig.titel,
